
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_cap_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_cap", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.284167467792343e+00, -4.201931594863347e+00, -4.086777674506889e+00, -3.927426680454344e+00, -3.710644125530820e+00, -3.422883680959710e+00, -3.054161329788116e+00, -2.605098052467226e+00, -2.096609931604733e+00, -1.574559882922267e+00, -1.076330861599328e+00, -7.041616470102019e-01, -6.005716034869418e-01, -4.967316329203987e-01, -3.638887198654220e-01, -2.438922650826049e-01, -1.706468586250828e-01, -1.549427823004312e-01, -1.889704885212013e-01, -2.552944406152627e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


